import type { Model, Provider } from "@earendil-works/pi-ai";
import { createModels } from "@earendil-works/pi-ai/models";
import { cloudflareAIGatewayProvider } from "@earendil-works/pi-ai/providers/cloudflare-ai-gateway";

export const GLM_5_3_FLASH_ID = "workers-ai/@cf/zai-org/glm-5.3-flash";

// Same tuning as pipeline/src/agents/model-provider.ts. pi-ai 1.4.0's catalog already
// carries contextWindow 1,048,576, but still maxTokens 1,048,576, no thinkingLevelMap,
// and compat.supportsReasoningEffort false.
const tune = <M>(model: M): M => {
  const chat = model as unknown as Model<"openai-completions">;

  if (chat.id !== GLM_5_3_FLASH_ID) {
    return model;
  }

  return {
    ...chat,
    contextWindow: 1_048_576,
    maxTokens: 131_072,
    thinkingLevelMap: { off: "low", low: "low", medium: "medium", high: "high", xhigh: "xhigh", max: "max" },
    compat: { ...chat.compat, supportsReasoningEffort: true },
  } as unknown as M;
};

const tunedGatewayProvider = (): Provider => {
  const base = cloudflareAIGatewayProvider() as unknown as Provider;

  return {
    ...base,
    getModels: () => base.getModels().map(tune),
    getAllModels: () => (base.getAllModels?.() ?? base.getModels()).map(tune),
  };
};

export const agentModels = () => {
  const models = createModels();
  models.setProvider(tunedGatewayProvider());
  return models;
};
