import { Type } from "@earendil-works/pi-ai";
import type { ToolExecutionApi } from "@earendil-works/pi-durable";
import { defineDoc, defineTool } from "@earendil-works/pi-durable";
import { Context as EffectContext, Data, Effect } from "effect";
import type { Context as ChordContext } from "@earendil-works/chord";

export const RecipesDoc = defineDoc<{ submissions: string[] }>({
  kind: "spike.recipes",
  version: 1,
  scope: "conversation",
  history: "latest",
  fork: "initial",
  initial: () => ({ submissions: [] }),
  checkpointWhen: () => false,
});

class RecipeStoreError extends Data.TaggedError("RecipeStoreError")<{ cause: unknown }> {}

// The store the Effect program depends on, provided per call from the tool's api.
class RecipeStore extends EffectContext.Service<
  RecipeStore,
  { append: (script: string) => Effect.Effect<number, RecipeStoreError> }
>()("RecipeStore") {}

const validate = (script: string, attempt: number) =>
  Effect.gen(function* () {
    if (attempt === 1) {
      return "REJECTED: footnote markers (sup.fn-ref) leak into the second paragraph's display, and the heading self-links (a.anchor) are not ignored. Add both to ignores and submit again.";
    }

    if (!script.includes("export")) {
      return "REJECTED: the script exports nothing.";
    }

    return "ACCEPTED: the recipe validates cleanly. Reply with the settled script.";
  });

const submit = (script: string) =>
  Effect.gen(function* () {
    const store = yield* RecipeStore;
    const attempt = yield* store.append(script);
    yield* Effect.logInfo(`submit_recipe attempt ${attempt}`);
    return yield* validate(script, attempt);
  });

const storeFor = (api: ToolExecutionApi, context: ChordContext) => ({
  append: (script: string) =>
    Effect.tryPromise({
      try: () =>
        api.commit(async (tx) => {
          const doc = await tx.doc(RecipesDoc, api.conversationId);
          doc.submissions.push(script);
          return doc.submissions.length;
        }, context),
      catch: (cause) => new RecipeStoreError({ cause }),
    }),
});

export const submitRecipeTool = (beforeExecute: (api: ToolExecutionApi) => void) =>
  defineTool({
    name: "submit_recipe",
    description: "Submit a complete recipe module's source. Returns ACCEPTED or REJECTED with the reason.",
    parameters: Type.Object({ script: Type.String({ description: "The full recipe module source" }) }),
    execute: async (args, api, context) => {
      beforeExecute(api);
      const text = await Effect.runPromise(submit(args.script).pipe(Effect.provideService(RecipeStore, storeFor(api, context))));
      return { output: [{ type: "text", text }] };
    },
  });
