import articleHtml from "../fixtures/article.html";
import { agentModels, GLM_5_3_FLASH_ID } from "./model-provider.ts";
import { RecipesDoc, submitRecipeTool } from "./recipe-tool.ts";

const context = BACKGROUND_CONTEXT;

const INSTRUCTIONS = `You author extraction recipes for one article at a time.

Call fetch_article to get the article's html. Write the whole recipe module on your first try: a JavaScript ES module exporting container (a selector string), ignores (a list of { selector, reason }) and extract($, toMarkdown). Call submit_recipe with it, read the result, fix whatever it names, and submit again. Repeat until it says ACCEPTED, then reply with one fenced json block: {"kind": "script", "source": "<the accepted module>"}. Keep the module short.`;

export type CrashMode = "none" | "tool" | "turn";

export interface RunResult {
  conversationId: string;
  status: string;
  submissions: number;
  entries: { kind: string; summary: string }[];
  usage: unknown;
  log: string[];
}

const summarize = (entry: EntryRecord) => {
  const message = entry.model?.[0] as
    | { role: string; content: unknown; toolName?: string; stopReason?: string }
    | undefined;

  if (message == null) {
    return "";
  }

  const parts = Array.isArray(message.content) ? message.content : [{ type: "text", text: String(message.content) }];
  const text = parts
    .map((part: { type: string; text?: string; name?: string; arguments?: unknown }) =>
      part.type === "toolCall" ? `toolCall:${part.name}` : part.type === "text" ? (part.text ?? "") : part.type,
    )
    .join(" | ");

  return `${message.role}${message.toolName == null ? "" : `(${message.toolName})`}: ${text.replace(/\s+/g, " ").slice(0, 160)}`;
};

export class AuthorAgent extends DurableObject<Env> {
  #harness!: Harness;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);

    this.#log(`constructor (instance start)`);

    void ctx.blockConcurrencyWhile(async () => {
      const fallback = Date.now() + 60_000;
      const current = await ctx.storage.getAlarm();

      if (current === null || current > fallback) {
        await ctx.storage.setAlarm(fallback);
      }

      const storage = await openDurableObjectSqliteStorage(ctx.storage);
      const onWake = (wake: Wake) => void this.#arm(wake).catch(() => ctx.abort("Alarm write failed"));

      this.#harness = await Harness.open(
        storage,
        {
          models: agentModels(),
          registry: this.#registry(),
          onWake,
          onReport: (error, info) => this.#log(`report ${info.type}: ${String(error)}`),
        },
        context,
      );

      await this.#arm(this.#harness.wake());
      const inspection = await this.#harness.inspect(context);
      this.#log(`opened; live tasks: ${JSON.stringify(inspection.tasks.map((task) => `${task.record.kind}:${task.record.state.status}`))}`);
      this.#harness.resume();
    });
  }

  override async alarm(): Promise<void> {
    this.#log(`alarm fired`);
    await this.#arm({ ...this.#harness.wake(), active: true });
