        const requests = ((this.ctx.storage.kv.get("requests") as number | undefined) ?? 0) + 1;
        this.ctx.storage.kv.put("requests", requests);
        this.#log(`model request #${requests} (${request.messages.length} messages)`);

        if (requests === 2 && this.ctx.storage.kv.get("crash") === "turn" && this.ctx.storage.kv.get("crashed") !== true) {
