import { Data, Effect, Schedule } from "effect";
import type { CrashMode, RunResult } from "./agent.ts";

export { AuthorAgent } from "./agent.ts";

class AgentCallError extends Data.TaggedError("AgentCallError")<{ message: string }> {}

// A stand-in for a Workflow step: the same id and requestId on every attempt, retried on failure.
const runAuthor = (env: Env, id: string, message: string, requestId: string, crash: CrashMode) =>
  Effect.gen(function* () {
    const attempt = { n: 0 };

    const result = yield* Effect.tryPromise({
      try: () => {
        attempt.n += 1;
        console.log(`SPIKE caller attempt ${attempt.n} for ${id}/${requestId}`);
        return env.AUTHOR.getByName(id).run(message, requestId, crash) as Promise<RunResult>;
      },
      catch: (cause) => new AgentCallError({ message: String(cause) }),
    }).pipe(
      Effect.tapError((error) => Effect.logWarning(`caller attempt failed: ${error.message}`)),
      Effect.retry(Schedule.spaced("2 seconds").pipe(Schedule.both(Schedule.recurs(4)))),
    );

    return { attempts: attempt.n, ...result };
  });

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const id = url.searchParams.get("id") ?? "default";

    if (url.pathname === "/state") {
      return Response.json(await env.AUTHOR.getByName(id).state());
    }

    if (url.pathname === "/run" && request.method === "POST") {
      const body = (await request.json()) as { message: string; requestId: string; crash?: CrashMode };
      const program = runAuthor(env, id, body.message, body.requestId, body.crash ?? "none").pipe(
        Effect.map((result) => Response.json(result)),
        Effect.catchTag("AgentCallError", (error) => Effect.succeed(Response.json({ error: error.message }, { status: 502 }))),
      );

      return Effect.runPromise(program);
    }

    return new Response("not found", { status: 404 });
  },
} satisfies ExportedHandler<Env>;
